const policies = [
  {
    source: "DEMO - Card Fraud Investigation Standard",
    section: "2.1 Transaction Triage",
    policy_text: `DEMO POLICY - NOT A REAL BANK POLICY.
Section 2.1 Transaction Triage
When a card transaction is flagged as potentially suspicious, investigators should review the amount relative to the customer's normal spend, transaction location, merchant familiarity, time of transaction, recent transaction velocity, authentication context and available merchant risk indicators. A single indicator should not normally be treated as conclusive evidence of fraud; decisions should weigh the combined evidence.`
  },
  {
    source: "DEMO - Card Fraud Investigation Standard",
    section: "3.2 Customer Verification",
    policy_text: `DEMO POLICY - NOT A REAL BANK POLICY.
Section 3.2 Customer Verification
For higher-risk cases, the recommended response is to verify the transaction with the customer via an approved contact channel, without disclosing unnecessary sensitive information. If the customer confirms the transaction, record the verification outcome. If the customer denies it, escalate according to the card fraud handling process.`
  },
  {
    source: "DEMO - Card Fraud Investigation Standard",
    section: "4.1 Temporary Restrictions",
    policy_text: `DEMO POLICY - NOT A REAL BANK POLICY.
Section 4.1 Temporary Restrictions
A temporary card restriction may be recommended when multiple high-risk indicators are present and customer verification cannot be completed promptly. Any restriction affecting a customer must follow the organisation's approved authorisation process. An AI assistant may recommend a review or restriction but must not independently execute a customer-impacting action.`
  },
  {
    source: "DEMO - Fraud Operations Escalation Guide",
    section: "5.3 Escalation Criteria",
    policy_text: `DEMO POLICY - NOT A REAL BANK POLICY.
Section 5.3 Escalation Criteria
Escalate a case for manual fraud review when there is strong evidence of account compromise, repeated suspicious activity, customer denial of a transaction, materially elevated merchant risk, or insufficient information to reach a reliable conclusion. The case record should include the key risk indicators, evidence reviewed, relevant policy references and the recommended next action.`
  },
  {
    source: "DEMO - Responsible AI for Fraud Operations",
    section: "1.4 Human Oversight",
    policy_text: `DEMO POLICY - NOT A REAL BANK POLICY.
Section 1.4 Human Oversight
AI-generated fraud investigation summaries and recommendations are decision-support outputs only. Final decisions that may block a card, decline service, contact a customer, lodge a fraud outcome or otherwise materially affect a customer require appropriate human review and must follow authorised operational procedures.`
  }
];
return policies.map(p => ({ json: p }));

const base = $('Prepare AI Investigation Case').item.json;
let raw = $json.output ?? $json.text ?? $json;
let parsed = null;

if (typeof raw === 'object' && raw !== null) {
  parsed = raw;
} else {
  const cleaned = String(raw).replace(/```json/gi, '').replace(/```/g, '').trim();
  try { parsed = JSON.parse(cleaned); } catch (e) { parsed = null; }
}

return [{
  json: {
    transaction_id: base.transaction_id,
    customer_id: base.customer_id,
    amount: base.amount,
    currency: base.currency,
    merchant: base.merchant,
    timestamp: base.timestamp ?? null,
    fraud_risk: {
      score: base.risk_score,
      level: base.risk_level,
      indicators: base.risk_indicators,
      scoring_version: base.scoring_version
    },
    investigation: parsed ?? {
      status: 'AI_OUTPUT_PARSE_FAILED',
      raw_output: typeof raw === 'string' ? raw : JSON.stringify(raw),
      recommended_action: 'MANUAL_REVIEW'
    },
    final_decision: 'HUMAN_REVIEW_REQUIRED',
    demo_disclaimer: 'Portfolio/demo workflow only. Not a production fraud decisioning system.'
  }
}];

const c = $json;
return [{
  json: {
    transaction_id: c.transaction_id,
    customer_id: c.customer_id,
    amount: c.amount,
    currency: c.currency,
    merchant: c.merchant,
    timestamp: c.timestamp ?? null,
    fraud_risk: {
      score: c.risk_score,
      level: c.risk_level,
      indicators: c.risk_indicators,
      scoring_version: c.scoring_version
    },
    investigation: {
      status: 'NOT_ESCALATED_TO_AI_AGENT',
      reason: 'Prototype risk score is below the investigation threshold of 60.',
      recommended_action: 'CONTINUE_STANDARD_MONITORING'
    },
    final_decision: 'NO_AUTOMATED_CUSTOMER_ACTION',
    demo_disclaimer: 'Portfolio/demo workflow only. Not a production fraud decisioning system.'
  }
}];

